import React from 'react';
import './Offers.css';
import { useNavigate } from 'react-router-dom';

const Offers = () => {
  const navigate = useNavigate();

  return (
    <section className="offers">
      <div className="offers-content">
        <span className="offers-tag">🔥 Limited Time Deal</span>

        <h1>
          Upgrade Your
          <br />
          Style Today
        </h1>

        <p>
          Discover the latest fashion collections with exclusive discounts,
          premium quality, and trending styles made just for you.
        </p>

        <div className="offers-buttons">
          <button
            className="shop-btn"
            onClick={() => navigate('/womens')}
          >
            Shop Collection
          </button>

          <button
            className="explore-btn"
            onClick={() => navigate('/mens')}
          >
            Explore More
          </button>
        </div>
      </div>
    </section>
  );
};

export default Offers;
